var n=`0087-salata-de-boeuf`;var a=`world-0087`;var i=`RO`;var o=`eastern-europe`;var r=4;var s=90;var d={en:`Salată de Boeuf`,ua:`Салата де бьоф`};var l={en:`A classic dish from Romania, featuring potato, carrot, beef chuck, chicken egg. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Румунія. Основні складники: картопля, морква, яловича лопатка, куряче яйце. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var c=[{en:`Simmer beef until tender and potatoes and carrots until cooked, using the water provided. Cool all components completely, then dice them evenly.`,ua:`Відваріть яловичину до м’якості, а картоплю й моркву до готовності у зазначеній воді. Повністю остудіть і наріжте однаковими кубиками.`,t:[`boiling`],m:60,i:[[`potato`,360,`g`],[`carrot`,260,`g`],[`beef-chuck`,320,`g`],[`water`,1100,`ml`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,3,`pcs`]]},{en:`Dice the cooked beef, vegetables and pickles; add drained canned peas and mix gently.`,ua:`Наріжте відварену яловичину, овочі та квашені огірки, додайте відціджений консервований горошок і обережно перемішайте.`,t:[`chopping`,`dicing`],m:15,i:[[`fermented-cucumber`,220,`g`],[`canned-green-peas`,210,`g`]]},{en:`Fold in the dressing ingredients, season to taste and serve, or chill briefly as appropriate.`,ua:`Обережно змішайте із заправкою, приправте до смаку й подавайте або трохи охолодіть за потреби.`,t:[`tossing`,`seasoning`],m:6,i:[[`mayonnaise`,220,`g`],[`dijon-mustard`,15,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var g={slug:n,id:a,country:`RO`,region:o,servings:4,minutes:90,title:d,text:l,steps:c};export{i as country,g as default,a as id,s as minutes,o as region,r as servings,n as slug,c as steps,l as text,d as title};